function(p_param, funcs) { //如果funcs为空则直接返回promise
            var param = angular.copy(p_param)
                /*
                 * param:{ method :"GET"/"POST", url :"someUrl", params
                 * :{key1:value1,key2:value2}, data :{string|Object}, timeout
                 * :{number|Promise} }
                 */
            if (param.headers) {
                param.headers["X-Requested-With"] = "XMLHttpRequest";
            } else {
                param.headers = {
                    "X-Requested-With": "XMLHttpRequest",
                };
            }
            if (param.method.toLowerCase() == "get") {
                if (param.params == undefined) {
                    param.params = {
                        m: new Date().getTime()
                    };

                } else if (param.params.m == undefined) {
                    param.params.m = new Date().getTime();
                } else {
                    param.params["m" + (new Date().getTime())] = new Date().getTime();
                }
            }
            if (funcs) { //回调方式
                return $http(param).then(function(obj) {
                    // success
                    if (obj.data && obj.data.status) {
                        var status = obj.data.status + "";
                        if (!status.match(/^2\w+/)) { //放开 以2开头的所有

                            $iq_httpError.dealError(obj); //通用错误处理

                            if (funcs.error) {
                                funcs.error(obj);
                            }
                            return;
                        }
                    }
                    if (funcs.success) {
                        funcs.success(obj);
                    }
                }, function(obj) {
                    //console.log(param);
                    // error
                    if (funcs.error) {
                        funcs.error(obj);
                    }
                });
            } else { //promise方式
                //              return $http(param);
                var def = $q.defer();
                $http(param).then(function(obj) {

                    if (obj.data && obj.data.status) {
                        var status = obj.data.status + "";
                        if (!status.match(/^2\w+/)) { //放开 以2开头的所有

                            $iq_httpError.dealError(obj);

                            def.reject(obj);
                            return def.promise;
                        } else {
                            $iq_httpError.logined();
                        }
                    }
                    def.resolve(obj);
                }, function(error) {
                    console.log(param);
                    def.reject(error);
                })
                return def.promise;
            }
        }

